package entpay

const localAgentHTML = `<!doctype html>
<html lang="zh-CN" data-language="zh">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <meta name="color-scheme" content="light">
  <title>EntPay 本地确认</title>
  <link rel="stylesheet" href="style.css">
</head>
<body>
  <header><a href="/" class="brand"><b>E</b><span>EntPay<small data-t="local">本地 Agent</small></span></a><div class="local"><i></i><span data-t="private">仅在这台电脑运行</span></div><button id="language" type="button">EN</button></header>
  <main>
    <div class="steps" aria-label="Payment progress"><span data-step="approval"><i></i><b data-t="approveStep">确认</b></span><span data-step="paying"><i></i><b data-t="payStep">签名</b></span><span data-step="confirming"><i></i><b data-t="confirmStep">确认中</b></span><span data-step="verifying"><i></i><b data-t="verifyStep">验收</b></span><span data-step="complete"><i></i><b data-t="completeStep">完成</b></span></div>
    <section id="loading" class="state"><span class="spinner"></span><h1 data-t="reading">正在安全读取账单</h1><p data-t="readingBody">本地 Agent 正在重新核对商家的公钥、签名、价格和请求内容。</p></section>
    <section id="approval" class="approval" hidden>
      <div class="summary"><p data-t="confirmTitle">确认这笔 Agent 支付</p><h1 id="product">--</h1><p id="description">--</p><div class="amount"><span data-t="payAmount">你将支付</span><strong id="amount">--</strong><small id="limit">--</small></div></div>
      <div class="facts"><div><span data-t="merchant">收款商家</span><code id="merchant">--</code></div><div><span data-t="request">你的请求</span><pre id="input">--</pre></div><div><span data-t="expires">账单有效期</span><strong id="expires">--</strong></div><div><span data-t="confirmations">交付要求</span><strong id="confirmations">--</strong></div></div>
      <div class="safety"><b data-t="safety">付款前已由本地代码验证</b><span data-t="safetyBody">商家签名、商品价格、输入哈希、网络和付款上限均已匹配。确认后才会使用本地钱包签名。</span></div>
      <div class="actions"><button id="reject" class="reject" type="button" data-t="reject">拒绝，不付款</button><button id="approve" class="approve" type="button"><span data-t="approve">确认支付</span><b>→</b></button></div>
    </section>
    <section id="progress" class="state" hidden><div class="pulse-ring"><i></i></div><p id="stage-label">--</p><h1 id="message">--</h1><span data-t="keepOpen">请保持此页面打开。本地 Agent 会自动完成余下步骤。</span></section>
    <section id="result" class="result" hidden><div class="check">✓</div><p data-t="done">支付与交付均已验证</p><h1 id="result-title">--</h1><div class="result-grid"><div><span data-t="transaction">交易 ID</span><code id="transaction">--</code></div><div><span data-t="receipt">签名收据</span><code id="receipt">--</code></div><div id="artifact-row"><span data-t="saved">文件已保存</span><code id="artifact">--</code></div></div><button id="close" type="button" data-t="close">完成</button></section>
    <section id="error" class="error" hidden><b>!</b><h1 data-t="stopped">付款已停止</h1><p id="error-message">--</p><span data-t="noRetry">没有创建新的付款。请返回商家页面重新开始。</span></section>
    <section id="empty" class="state" hidden><b class="empty-mark">E</b><h1 data-t="noRequest">还没有待确认的账单</h1><p data-t="noRequestBody">请从商家的 EntPay 页面选择服务并创建账单。</p></section>
  </main>
  <footer><span>127.0.0.1</span><span data-t="boundary">钱包密钥不会离开这台电脑</span><span>ENTPAY-V1</span></footer>
  <script src="app.js"></script>
</body>
</html>`

const localAgentJavaScript = `const $=id=>document.getElementById(id);const state={language:(localStorage.getItem("entpay-local-language")||navigator.language).toLowerCase().startsWith("zh")?"zh":"en",id:null,status:null,timer:null};const copy={zh:{local:"本地 Agent",private:"仅在这台电脑运行",approveStep:"确认",payStep:"签名",confirmStep:"确认中",verifyStep:"验收",completeStep:"完成",reading:"正在安全读取账单",readingBody:"本地 Agent 正在重新核对商家的公钥、签名、价格和请求内容。",confirmTitle:"确认这笔 Agent 支付",payAmount:"你将支付",merchant:"收款商家",request:"你的请求",expires:"账单有效期",confirmations:"交付要求",safety:"付款前已由本地代码验证",safetyBody:"商家签名、商品价格、输入哈希、网络和付款上限均已匹配。确认后才会使用本地钱包签名。",reject:"拒绝，不付款",approve:"确认支付",keepOpen:"请保持此页面打开。本地 Agent 会自动完成余下步骤。",done:"支付与交付均已验证",transaction:"交易 ID",receipt:"签名收据",saved:"文件已保存",close:"完成",stopped:"付款已停止",noRetry:"没有创建新的付款。请返回商家页面重新开始。",noRequest:"还没有待确认的账单",noRequestBody:"请从商家的 EntPay 页面选择服务并创建账单。",boundary:"钱包密钥不会离开这台电脑",rejected:"你已拒绝付款，没有创建任何交易。",limit:v=>"本地单笔上限 "+v,blocks:v=>v+" 个区块确认"},en:{local:"Local Agent",private:"Running only on this computer",approveStep:"Approve",payStep:"Sign",confirmStep:"Confirm",verifyStep:"Verify",completeStep:"Done",reading:"Securely reading the invoice",readingBody:"The local Agent is checking the merchant key, signature, price and request again.",confirmTitle:"Confirm this Agent payment",payAmount:"You will pay",merchant:"Merchant",request:"Your request",expires:"Invoice expiry",confirmations:"Delivery requirement",safety:"Verified locally before payment",safetyBody:"Merchant signature, product price, input hash, network and spending limit all match. Your local wallet signs only after confirmation.",reject:"Reject without paying",approve:"Confirm payment",keepOpen:"Keep this page open. The local Agent will finish the remaining steps automatically.",done:"Payment and delivery verified",transaction:"Transaction ID",receipt:"Signed receipt",saved:"File saved",close:"Done",stopped:"Payment stopped",noRetry:"No new payment was created. Return to the merchant and start again.",noRequest:"No payment is waiting",noRequestBody:"Choose a service and create an invoice on a merchant EntPay page.",boundary:"Wallet keys never leave this computer",rejected:"You rejected this payment. No transaction was created.",limit:v=>"Local per-payment limit "+v,blocks:v=>v+(v===1?" confirmation":" confirmations")}};const products={"generated-photo":{zh:["生成照片","根据你的画面描述生成并交付一张原创 JPEG 图片。"]},"network-report":{zh:["网络状态报告","读取并比较 Entcoin 公共节点，交付可验证的网络报告。"]}};const stages={zh:{paying:["本地签名","正在使用本机钱包签名并广播付款"],confirming:["等待确认","付款已广播，正在等待链上确认"],verifying:["验证交付","正在验证签名收据和交付文件哈希"],complete:["完成","收据和交付均已验证"]},en:{paying:["LOCAL SIGNING","Signing and broadcasting with the local wallet"],confirming:["CONFIRMING","Payment broadcast; waiting for chain confirmation"],verifying:["VERIFYING","Verifying the signed receipt and delivery hashes"],complete:["COMPLETE","Receipt and delivery verified"]}};const t=k=>copy[state.language][k];const amount=v=>(Number(v)/1e8).toFixed(8)+" ENT";const productText=p=>products[p.id]?.[state.language]||[p.name,p.description];function translate(){document.documentElement.lang=state.language==="zh"?"zh-CN":"en";document.documentElement.dataset.language=state.language;document.querySelectorAll("[data-t]").forEach(el=>{const value=t(el.dataset.t);if(typeof value==="string")el.textContent=value});$("language").textContent=state.language==="zh"?"EN":"中文";localStorage.setItem("entpay-local-language",state.language);if(state.status)render(state.status)}function show(id){for(const name of ["loading","approval","progress","result","error","empty"])$(name).hidden=name!==id}function decodeFragment(){const value=new URLSearchParams(location.hash.slice(1)).get("handoff");history.replaceState(null,"",location.pathname);if(!value)return null;const base=value.replace(/-/g,"+").replace(/_/g,"/");const bytes=Uint8Array.from(atob(base),c=>c.charCodeAt(0));return JSON.parse(new TextDecoder().decode(bytes))}async function json(url,options={}){const response=await fetch(url,{...options,headers:{"Content-Type":"application/json",Accept:"application/json",...(options.headers||{})}});const result=await response.json();if(!response.ok)throw new Error(result.error||"HTTP "+response.status);return result}async function acceptHandoff(payload){const status=await json("v1/handoffs",{method:"POST",body:JSON.stringify(payload)});state.id=status.id;render(status)}function render(status){state.status=status;const product=productText(status.product);document.querySelectorAll("[data-step]").forEach((el,index)=>{const order=["approval","paying","confirming","verifying","complete"];const active=Math.max(0,order.indexOf(status.stage));el.classList.toggle("active",index<=active);el.classList.toggle("current",index===active)});if(status.stage==="approval"){show("approval");$("product").textContent=product[0];$("description").textContent=product[1];$("amount").textContent=amount(status.invoice.amount);$("limit").textContent=t("limit")(amount(status.maximum_amount));$("merchant").textContent=status.invoice.merchant;$("input").textContent=JSON.stringify(status.input,null,2);$("expires").textContent=new Date(status.invoice.expires_at).toLocaleString(state.language==="zh"?"zh-CN":"en-US");$("confirmations").textContent=t("blocks")(status.invoice.confirmations);return}if(status.stage==="complete"){show("result");$("result-title").textContent=product[0];$("transaction").textContent=status.transaction_id;$("receipt").textContent=status.delivery.receipt.signature;$("artifact-row").hidden=!status.artifact_output;$("artifact").textContent=status.artifact_output;clearInterval(state.timer);return}if(status.stage==="error"||status.stage==="rejected"){show("error");$("error-message").textContent=status.stage==="rejected"?t("rejected"):(status.error||status.message);clearInterval(state.timer);return}show("progress");const stage=stages[state.language][status.stage]||[status.stage.toUpperCase(),status.message];$("stage-label").textContent=stage[0];$("message").textContent=stage[1]}async function poll(){if(!state.id)return;try{render(await json("v1/handoffs/"+state.id))}catch(error){show("error");$("error-message").textContent=error.message;clearInterval(state.timer)}}$("language").addEventListener("click",()=>{state.language=state.language==="zh"?"en":"zh";translate()});$("approve").addEventListener("click",async()=>{try{render(await json("v1/handoffs/"+state.id+"/approve",{method:"POST",body:"{}"}));state.timer=setInterval(poll,1200)}catch(error){show("error");$("error-message").textContent=error.message}});$("reject").addEventListener("click",async()=>{try{render(await json("v1/handoffs/"+state.id+"/reject",{method:"POST",body:"{}"}))}catch(error){show("error");$("error-message").textContent=error.message}});$("close").addEventListener("click",()=>window.close());translate();const payload=decodeFragment();if(payload)acceptHandoff(payload).catch(error=>{show("error");$("error-message").textContent=error.message});else show("empty");`

const localAgentCSS = `:root{--paper:#f4f6f2;--ink:#111617;--blue:#245cff;--green:#00a878;--red:#f05b4f;--yellow:#ffd84d;--muted:#697477;--line:rgba(17,22,23,.16);--sans:"Segoe UI","Noto Sans SC",Arial,sans-serif;--mono:Consolas,"SFMono-Regular",monospace;color-scheme:light;letter-spacing:0}*{box-sizing:border-box}html,body{margin:0;min-width:320px;min-height:100%;background:var(--paper);color:var(--ink);font:14px/1.55 var(--sans);letter-spacing:0}button{font:inherit;letter-spacing:0}[hidden]{display:none!important}header{height:72px;padding:0 clamp(18px,5vw,70px);display:grid;grid-template-columns:1fr auto 1fr;align-items:center;border-bottom:1px solid var(--line)}.brand{display:flex;align-items:center;gap:11px;color:inherit;text-decoration:none}.brand>b{width:34px;height:34px;display:grid;place-items:center;border-radius:50%;background:var(--blue);color:#fff}.brand>span{display:flex;flex-direction:column;font-size:16px;font-weight:800}.brand small{color:var(--muted);font:500 8px var(--mono)}.local{display:flex;align-items:center;gap:9px;color:var(--muted);font:500 9px var(--mono)}.local i{width:7px;height:7px;border-radius:50%;background:var(--green);box-shadow:0 0 0 5px rgba(0,168,120,.12)}#language{justify-self:end;width:46px;height:38px;border:1px solid var(--ink);background:transparent;cursor:pointer;font:500 10px var(--mono)}main{width:min(1100px,calc(100% - 36px));min-height:calc(100dvh - 112px);margin:auto;padding:42px 0 70px}.steps{position:relative;display:grid;grid-template-columns:repeat(5,1fr);margin-bottom:70px}.steps:before{content:"";position:absolute;left:0;right:0;top:6px;height:1px;background:var(--line)}.steps span{position:relative;padding-top:22px;color:#9aa2a4;font:500 9px var(--mono)}.steps i{position:absolute;top:0;left:0;width:13px;height:13px;border-radius:50%;border:1px solid #aab2b3;background:var(--paper);transition:.3s}.steps .active{color:var(--ink)}.steps .active i{border-color:var(--blue);background:var(--blue)}.steps .current i{box-shadow:0 0 0 8px rgba(36,92,255,.12)}.approval{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(300px,.9fr);column-gap:8vw}.summary>p,.result>p{margin:0;color:var(--blue);font:500 10px var(--mono)}.summary h1,.state h1,.result h1,.error h1{margin:14px 0 16px;font-size:52px;line-height:1.02}.summary>p+ h1+ p{max-width:580px;color:var(--muted);font-size:16px}.amount{margin-top:52px;padding:25px 0;border-top:1px solid var(--ink);border-bottom:1px solid var(--ink)}.amount span,.amount strong,.amount small{display:block}.amount span{font:500 9px var(--mono)}.amount strong{margin:8px 0;font:700 34px var(--mono)}.amount small{color:var(--muted)}.facts{border-top:1px solid var(--ink)}.facts>div{padding:18px 0;border-bottom:1px solid var(--line)}.facts span,.result-grid span{display:block;margin-bottom:7px;color:var(--muted);font:500 9px var(--mono)}.facts code,.facts pre,.result-grid code{margin:0;font:500 11px/1.6 var(--mono);overflow-wrap:anywhere;white-space:pre-wrap}.safety{grid-column:1/-1;margin-top:45px;padding:22px 25px;display:grid;grid-template-columns:.4fr 1fr;gap:20px;background:#e4eee9;border-left:4px solid var(--green)}.safety span{color:#4f625a}.actions{grid-column:1/-1;margin-top:12px;display:grid;grid-template-columns:1fr 1fr;gap:8px}.actions button{height:58px;padding:0 20px;border:1px solid var(--ink);cursor:pointer;font-weight:800}.reject{background:transparent}.approve{display:flex;align-items:center;justify-content:space-between;background:var(--ink);color:#fff}.approve:hover{background:var(--blue);border-color:var(--blue)}.state{min-height:520px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center}.state>p,.state>span{max-width:520px;color:var(--muted)}.spinner{width:45px;height:45px;border:2px solid var(--line);border-top-color:var(--blue);border-radius:50%;animation:spin 1s linear infinite}.pulse-ring{width:86px;height:86px;display:grid;place-items:center;border:1px solid var(--line);border-radius:50%}.pulse-ring i{width:20px;height:20px;border-radius:50%;background:var(--blue);box-shadow:0 0 0 0 rgba(36,92,255,.25);animation:pulse 1.7s infinite}.result,.error{max-width:850px;margin:60px auto}.check,.error>b{width:70px;height:70px;display:grid;place-items:center;border-radius:50%;background:var(--green);color:#fff;font-size:30px}.result-grid{margin-top:45px;border-top:1px solid var(--ink)}.result-grid>div{padding:18px 0;border-bottom:1px solid var(--line)}.result>button{width:100%;height:54px;margin-top:16px;border:0;background:var(--ink);color:#fff;font-weight:800}.error>b{background:var(--red)}.error p{font-size:16px}.error span{color:var(--muted)}.empty-mark{width:60px;height:60px;display:grid;place-items:center;border:1px solid var(--ink);border-radius:50%;font-size:24px}footer{min-height:40px;padding:0 clamp(18px,5vw,70px);display:grid;grid-template-columns:1fr auto 1fr;align-items:center;background:var(--ink);color:#aab5b5;font:500 8px var(--mono)}footer span:last-child{text-align:right}button:focus-visible,a:focus-visible{outline:3px solid var(--red);outline-offset:3px}@keyframes spin{to{transform:rotate(360deg)}}@keyframes pulse{70%{box-shadow:0 0 0 22px rgba(36,92,255,0)}}@media(max-width:720px){header{height:62px;padding:0 14px;grid-template-columns:1fr auto}.local{display:none}main{padding-top:28px}.steps{margin-bottom:48px}.steps b{display:none}.approval{display:block}.summary h1,.state h1,.result h1,.error h1{font-size:36px}.amount{margin-top:35px}.facts{margin-top:42px}.safety{display:block;margin-top:30px}.safety span{display:block;margin-top:8px}.actions{grid-template-columns:1fr}.reject{order:2}.state{min-height:470px}footer{min-height:66px;display:flex;flex-wrap:wrap;gap:8px 20px;padding:13px 16px}footer span:nth-child(2){order:3;width:100%}footer span:last-child{margin-left:auto}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation-duration:.001ms!important;animation-iteration-count:1!important;transition-duration:.001ms!important}}`
